package model

import (
	"errors"
	"time"
)

// ErrMediaFileNotFound is returned when no media row has the id.
var ErrMediaFileNotFound = errors.New("media file not found")

// MediaFile is one file a device uploaded: a photo from a camera, a short video
// or an audio note. The row keeps the metadata and the name on disk; the bytes
// live under the configured media directory.
type MediaFile struct {
	ID       int64
	DeviceID int64
	// FileName is the name on disk, generated by the server: the name the device
	// sent is kept in Attributes so a path traversal cannot escape the directory.
	FileName string
	// Type is image, video or audio; it selects the key the position carries.
	Type       string
	Size       int64
	MediaTime  time.Time
	Attributes Attributes
}

// Media types, matching the attribute names a position uses.
const (
	MediaTypeImage = "image"
	MediaTypeVideo = "video"
	MediaTypeAudio = "audio"
)

// AttrOriginalName keeps the uploaded file name.
const AttrOriginalName = "originalName"
